const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const link=u=>{try{const x=new URL(u);return x.protocol==='https:'&&!x.username&&!x.password?x.href:null;}catch{return null;}};
export function morningMarkup(plan){
 if(!plan)return '<div class="research-empty">今日计划尚未生成。每天北京时间8点自动留档；电脑需保持唤醒且本地服务运行。最晚09:00开始生成。</div>';
 const label=plan.preview?'预览 · 不留档':plan.late?'补生成 · 已冻结':'晨间计划 · 已冻结';
 const groups=[['指数','指数'],['ETF','ETF']];
 return `<div class="morning-summary"><div><span>${esc(label)} · ${esc(plan.date)}</span><h2>${esc(plan.summary)}</h2><p>收盘依据：${esc(plan.closeDate||'待补齐')} · 消息截止：${esc(clock(plan.cutoffAt))}</p><p>实际生成：${esc(clock(plan.generatedAt))} · 日线覆盖 ${plan.market.coverage}/${plan.market.total} · ${esc(plan.calendarStatus)}</p></div></div>
 <p class="research-caption">${esc(plan.executionNote)}</p>
 <details class="morning-warnings" open><summary>数据范围与执行前检查</summary>${plan.warnings.map(s=>`<p>${esc(s)}</p>`).join('')}</details>
 ${groups.map(([label,type])=>`<section class="morning-group"><h2>${label} · ${plan.items.filter(i=>type==='指数'?i.sector==='指数':i.sector.endsWith('ETF')).length} 个观察对象</h2><div class="morning-cards">${plan.items.filter(i=>type==='指数'?i.sector==='指数':i.sector.endsWith('ETF')).map(i=>`<article class="morning-card"><div class="morning-card-title"><h3>${esc(i.name)}</h3><span class="chip">${esc(i.status)}</span></div><p>${esc(i.reason)}</p>${Number.isFinite(i.close)?`<p>突破观察 ${i.pressure.toFixed(i.sector.endsWith('ETF')?3:2)} · 风险观察 ${i.support.toFixed(i.sector.endsWith('ETF')?3:2)}</p>`:''}<p class="muted">${esc(i.newsSummary||'数据待补齐')}</p><details><summary>执行条件与依据</summary>${i.conditions.map(c=>`<p><b>${esc(c.label)}：</b>${esc(c.text)}</p>`).join('')}<small>日线截至 ${esc(i.closeDate||'—')} · ${esc(i.source||'来源待确认')}；价位随本次计划冻结。</small></details></article>`).join('')}</div></section>`).join('')}
 <section class="morning-news"><h2>收盘后至生成时 · 已采集消息（${plan.news.items.length}）</h2><p class="muted">窗口 ${esc(clock(plan.news.from))} — ${esc(clock(plan.news.to))}；按关键词关联，不推断利好利空已被价格确认。</p><div class="morning-sources">${plan.news.sources.map(s=>`<span>${esc(s.name)}：${s.eligible?'生成前来源正常':'截止时刻状态未确认'}</span>`).join('')}</div>${plan.news.items.length?plan.news.items.map(n=>`<article><h3>${link(n.url)?`<a href="${esc(link(n.url))}" target="_blank" rel="noopener noreferrer">${esc(n.title)} ↗</a>`:esc(n.title)}</h3><p>${esc(n.source)} · 发布 ${esc(clock(n.publishedAt))} · 首次采到 ${esc(clock(n.firstObservedAt))}</p><p>${esc(n.interpretation)}${n.links.length?'；关联：'+esc(n.links.map(l=>l.name).join('、')):''}${n.risk?'；触发风险词，需核实':''}</p></article>`).join(''):'<p>本窗口暂无可用于计划的消息记录；这不代表没有消息。</p>'}</section>`;
}
